  (5163, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Pupil","organisation":"Guisborough Grammar School","detail":"In his maiden speech he thanked his teachers at Guisborough grammar school in Cleveland.","source":{"title":"Hansard: Planning, the Green Belt and Rural Affairs, maiden speech of Peter Prinsley (19 July 2024)","url":"https://hansard.parliament.uk/Commons/2024-07-19/debates/6A1FA3E9-41B0-434A-B13C-B6680AA87023/PlanningTheGreenBeltAndRuralAffairs"}},{"phase":"education","start":null,"end":null,"title":"Medical degree","organisation":"Sheffield Medical School","detail":"He was educated at Sheffield Medical School.","source":{"title":"Wikipedia: Peter Prinsley","url":"https://en.wikipedia.org/wiki/Peter_Prinsley"}},{"phase":"career","start":null,"end":null,"title":"Ear, nose and throat surgeon","organisation":"Norfolk and Norwich University Hospital","detail":"He was an ear, nose and throat surgeon for about 40 years and in 2024 was serving at Norfolk and Norwich University Hospital and James Paget Hospital.","source":{"title":"Suffolk News: Bury St Edmunds and Stowmarket's new Labour MP Peter Prinsley on his history making election (9 July 2024)","url":"https://www.suffolknews.co.uk/bury-st-edmunds/news/we-ve-finally-turned-a-tide-labour-s-peter-prinsley-on-wh-9373672/"}},{"phase":"career","start":null,"end":null,"title":"Ear, nose and throat surgeon","organisation":"James Paget Hospital","detail":"He was serving at James Paget Hospital as well as Norfolk and Norwich University Hospital at the time of his election.","source":{"title":"Suffolk News: Bury St Edmunds and Stowmarket's new Labour MP Peter Prinsley on his history making election (9 July 2024)","url":"https://www.suffolknews.co.uk/bury-st-edmunds/news/we-ve-finally-turned-a-tide-labour-s-peter-prinsley-on-wh-9373672/"}},{"phase":"career","start":null,"end":null,"title":"Regional director","organisation":"Royal College of Surgeons","detail":"He was a regional director for the Roy